    for (String str : strings) {
        maxLength = Math.max(maxLength, findLargestSubstringHelper(str));
    }

    return maxLength;
}

private int findLargestSubstringHelper(String str) {
    int maxLength = 0;
    for (int i = 0; i < str.length(); i++) {
        for (int j = i + 1; j <= str.length(); j++) {
            String subStr = str.substring(i, j);
            if (strings.contains(subStr) || strings.contains(subStr.reverse())) {
                maxLength = Math.max(maxLength, j - i);
            }
        }
    }

    return maxLength;
}

