}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
        // Sort the array
        Arrays.sort(arr);

        // Calculate the number of elements to remove
        int removeCount = (int) (arr.length * 0.1);

        // Remove the smallest 5% and largest 5% elements
        int start = removeCount;
        int end = arr.length - removeCount;
        int[] trimmedArr = Arrays.copyOfRange(arr, start, end);

        // Calculate the mean of the remaining elements
        double sum = 0;
        for (int num : trimmedArr) {
            sum += num;
        }
        double mean = sum / trimmedArr.length;

        return mean;
    }

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        throw new IllegalArgumentException("Array must be non-null and have an even length.");
    }

    int[] counts = new int[k];
    for (int num : arr) {
        counts[num % k]++;
    }

    for (int i = 1; i < k; i++) {
        if (counts[i] != counts[k - i]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the graph as an adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and calculate the time
    return dfs(0, graph, hasApple, new boolean[n], 0);
}

private int dfs(int node, List<List<Integer>> graph, boolean[] hasApple, boolean[] visited, int time) {
    visited[node] = true;
    int totalTime = 0;

    // Explore all neighbors
    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            totalTime += dfs(neighbor, graph, hasApple, visited, time + 1);
        }
    }

    // If the current node has an apple or any of its neighbors has an apple, add the time to collect the apple
    if (hasApple[node] || totalTime > 0) {
        totalTime += 2; // Add 2 for the time to move to the neighbor and back to the current node
    }

    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    int i = 0;
    while (i < s.length()) {
        // Pick the smallest character
        for (int j = 0; j < 26; j++) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }

        // Pick the largest character
        for (int j = 25; j >= 0; j--) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }
    }

    return result.toString();
}

