public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low > high) {
        return steppingNumbers;
    }
    steppingNumbers.add(0);
    steppingNumbers.add(1);
    steppingNumbers.add(2);
    steppingNumbers.add(3);
    steppingNumbers.add(4);
    steppingNumbers.add(5);
    steppingNumbers.add(6);
    steppingNumbers.add(7);
    steppingNumbers.add(8);
    steppingNumbers.add(9);

    for (int i = 1; i < steppingNumbers.size(); i++) {
        int current = steppingNumbers.get(i);
        if (current >= low && current <= high) {
            steppingNumbers.add(current);
        }
        if (current % 10 == 0 || current % 10 == 9) {
            continue;
        }
        int next = current * 10 + (current % 10 + 1);
        if (next <= high) {
            steppingNumbers.add(next);
        }
        next = current * 10 + (current % 10 - 1);
        if (next <= high) {
            steppingNumbers.add(next);
        }
    }

    steppingNumbers.sort(Integer::compare);
    return steppingNumbers;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countDigitOneHelper(i);
    }

    return count;
}

private static int countDigitOneHelper(int num) {
    if (num == 0) {
        return 0;
    }

    int count = 0;
    int power = 1;
    while (num >= power) {
        int digit = num / power % 10;
        if (digit == 1) {
            count += (num - power + 1) / power;
        } else if (digit > 1) {
            count += power;
        }
        power *= 10;
    }

    return count;
}

