public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        int n = A.length;
        int[] count = new int[n];
        Arrays.fill(count, 1);

        for (int i = 1; i < n; i++) {
            if (isPerfectSquare(A[i] + A[i - 1])) {
                count[i] = count[i - 1];
            } else {
                for (int j = 0; j < i; j++) {
                    if (isPerfectSquare(A[i] + A[j])) {
                        count[i] += count[j];
                    }
                }
            }
        }

        return count[n - 1];
    }

private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    // Find the nearest smaller element to the left for each bar
    leftSmaller[0] = -1;
    for (int i = 1; i < heights.length; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j];
        }
        leftSmaller[i] = j;
    }

    // Find the nearest smaller element to the right for each bar
    rightSmaller[heights.length - 1] = heights.length;
    for (int i = heights.length - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < heights.length && heights[j] >= heights[i]) {
            j = rightSmaller[j];
        }
        rightSmaller[i] = j;
    }

    // Calculate the area of each bar and find the maximum
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[index++] = mat[i][j];
        }
    }

    for (int i = 1; i < cols; i++) {
        for (int j = rows - 1; j >= 0; j--) {
            if (j + i < rows) {
                result[index++] = mat[j + i][i];
            }
        }
    }

    for (int i = 1; i < rows; i++) {
        for (int j = 0; j < cols - 1; j++) {
            if (j + i < cols) {
                result[index++] = mat[i][j + i];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1; // Return -1 if input is not positive
    }

    // Convert the integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Find the first digit that is not in its correct position
    for (int i = 0; i < digits.length - 1; i++) {
        if (digits[i] > digits[i + 1]) {
            // Swap the digits
            char temp = digits[i];
            digits[i] = digits[i + 1];
            digits[i + 1] = temp;

            // Sort the remaining digits in ascending order
            Arrays.sort(digits, i + 1, digits.length);

            // Convert the sorted array back to an integer
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, return -1
    return -1;
}

